import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const s=JSON.parse('{"title":"Ceph Month 2021: From Open Source to Open Ended in Ceph with Lua","description":"","frontmatter":{"title":"Ceph Month 2021: From Open Source to Open Ended in Ceph with Lua","date":"2021-06-15T00:00:00.000Z","updated":"2021-06-16T00:00:00.000Z","tags":["Ceph","Lua","Distributed Storage","Open Source","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_From_Open_Source_to_Open_Ended_in_Ceph_with_Lua.md","filePath":"posts/2021/Ceph_Month_2021_-_From_Open_Source_to_Open_Ended_in_Ceph_with_Lua.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Month_2021_-_From_Open_Source_to_Open_Ended_in_Ceph_with_Lua.md"};function h(r,e,n,u,p,_){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph中lua的集成与应用" tabindex="-1">会议主题：Ceph中Lua的集成与应用 <a class="header-anchor" href="#会议主题-ceph中lua的集成与应用" aria-label="Permalink to &quot;会议主题：Ceph中Lua的集成与应用&quot;">​</a></h4><h4 id="参会人员-ceph研发团队及相关领域专家" tabindex="-1">参会人员：Ceph研发团队及相关领域专家 <a class="header-anchor" href="#参会人员-ceph研发团队及相关领域专家" aria-label="Permalink to &quot;参会人员：Ceph研发团队及相关领域专家&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Seth简介</strong>：</p><ul><li>Seth是一个开源且免费的工具，旨在提供灵活的存储解决方案。</li><li>Ceph作为一个包含250万行C++代码的大型项目，具有复杂的架构和依赖关系。</li></ul></li><li><p><strong>Ceph的开放性</strong>：</p><ul><li>尽管Ceph是开源的，但并非所有用户都有能力或意愿对其核心代码进行修改。</li><li>为了增强用户的参与度和灵活性，Ceph提供了多种机制，如对象类（CLS）和Lua集成，允许用户在不修改核心代码的情况下进行定制。</li></ul></li><li><p><strong>Lua在Ceph中的应用</strong>：</p><ul><li>Lua是一种成熟且强大的编程语言，易于学习和使用。</li><li>Lua在Ceph中的应用包括注入Lua对象类（CLS），允许在OSD（Object Storage Daemon）中运行Lua代码。</li><li>Lua的轻量级特性使其适合处理并发请求，且与C++的集成效率高。</li></ul></li><li><p><strong>Lua集成的优势</strong>：</p><ul><li>提供简单易用的API，隐藏内部复杂结构，保持API的一致性。</li><li>支持零拷贝和零安装，简化开发和部署过程。</li><li>通过Lua集成，用户可以实现特定的业务逻辑和行为，而无需修改Ceph的核心代码。</li></ul></li><li><p><strong>具体应用案例</strong>：</p><ul><li>通过Lua脚本解决客户端元数据缺失的问题，增强系统的灵活性和可扩展性。</li><li>在RGW（RADOS Gateway）中集成Lua，提供更多的定制选项和集成点。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续探索和扩展Lua在Ceph中的应用，如压缩选项、对象分割等。</li><li>考虑在RGW中引入Lua层，以支持更多的逻辑处理和集成需求。</li><li>鼓励社区成员提出更多的使用案例和需求，以进一步丰富Lua在Ceph中的应用场景。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认Lua作为Ceph的扩展语言，提供更多的定制和集成选项。</li><li>继续推动Lua在Ceph中的应用，增强系统的灵活性和可扩展性。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>研发团队将深入研究Lua在Ceph中的具体应用场景，并制定详细的实施计划。</li><li>鼓励社区成员积极参与，提出更多的使用案例和需求，共同推动Ceph的发展。</li></ul><h4 id="会议结束时间-具体时间" tabindex="-1">会议结束时间：[具体时间] <a class="header-anchor" href="#会议结束时间-具体时间" aria-label="Permalink to &quot;会议结束时间：[具体时间]&quot;">​</a></h4><h4 id="下次会议安排-具体时间" tabindex="-1">下次会议安排：[具体时间] <a class="header-anchor" href="#下次会议安排-具体时间" aria-label="Permalink to &quot;下次会议安排：[具体时间]&quot;">​</a></h4>',13)])])}const c=a(o,[["render",h]]);export{s as __pageData,c as default};
